// Lifecycle status of a single auction.
enum AuctionStatus {
    ACTIVE, // still accepting bids
    ENDED   // closed, no further bids accepted
}

// The item being sold, with its starting price.
class Item {
    private final String itemId;      // unique id
    private final String title;        // display title
    private final double startingPrice; // the floor, shown before any real competition exists

    public Item(String itemId, String title, double startingPrice) {
        this.itemId = itemId;             // store id
        this.title = title;                 // store title
        this.startingPrice = startingPrice;   // store starting price
    }

    public String getItemId() { return itemId; }            // id getter
    public double getStartingPrice() { return startingPrice; } // starting price getter
}

// Tracks the live bidding state of one auction.
class Auction {
    private final String auctionId;   // unique id, e.g. A1
    private final String itemId;        // which item this sells
    private final String sellerId;        // who is selling it
    private String highestBidderId;         // current leader, null until the first bid
    private double highestMax;                // the leader's true maximum, never shown to anyone
    private double currentPrice;                // what a winner would actually pay right now
    private int endTime;                          // the virtual time this auction is scheduled to close
    private AuctionStatus status;                   // current lifecycle state

    public Auction(String auctionId, String itemId, String sellerId, double startingPrice, int endTime) {
        this.auctionId = auctionId;       // store id
        this.itemId = itemId;               // store item
        this.sellerId = sellerId;             // store seller
        this.highestBidderId = null;            // nobody has bid yet
        this.highestMax = 0.0;                    // no true maximum yet
        this.currentPrice = startingPrice;          // starts at the item's floor
        this.endTime = endTime;                       // store initial deadline
        this.status = AuctionStatus.ACTIVE;             // starts active
    }

    public String getAuctionId() { return auctionId; }           // id getter
    public String getHighestBidderId() { return highestBidderId; } // leader getter
    public void setHighestBidderId(String id) { this.highestBidderId = id; } // leader setter
    public double getHighestMax() { return highestMax; }            // leader's max getter
    public void setHighestMax(double max) { this.highestMax = max; }  // leader's max setter
    public double getCurrentPrice() { return currentPrice; }           // price getter
    public void setCurrentPrice(double price) { this.currentPrice = price; } // price setter
    public int getEndTime() { return endTime; }                          // end time getter
    public void setEndTime(int endTime) { this.endTime = endTime; }        // end time setter
    public AuctionStatus getStatus() { return status; }                     // status getter
    public void setStatus(AuctionStatus status) { this.status = status; }    // status setter
}

// One bidder's submitted maximum for a specific auction.
class Bid {
    private final String bidId;      // unique id, e.g. B1
    private final String auctionId;    // which auction this targets
    private final String bidderId;       // who placed it
    private final double maxAmount;        // the true maximum, never revealed to other bidders

    public Bid(String bidId, String auctionId, String bidderId, double maxAmount) {
        this.bidId = bidId;             // store id
        this.auctionId = auctionId;       // store auction
        this.bidderId = bidderId;           // store bidder
        this.maxAmount = maxAmount;           // store true maximum
    }

    public String getBidId() { return bidId; }           // id getter
    public String getBidderId() { return bidderId; }       // bidder getter
    public double getMaxAmount() { return maxAmount; }        // max getter
}

// Creates sequential, correctly-prefixed ids for auctions and bids.
class AuctionIdFactory {
    private int auctionCounter = 0; // running id counter for auctions
    private int bidCounter = 0;       // running id counter for bids

    public String nextAuctionId() {
        auctionCounter++;                  // bump id counter
        return "A" + auctionCounter;        // e.g. A1
    }

    public String nextBidId() {
        bidCounter++;                // bump id counter
        return "B" + bidCounter;      // e.g. B1
    }
}

