interface BidIncrementStrategy {
    double minIncrement(double currentPrice);
}

// A simple constant increment, regardless of how high the price has climbed.
class FixedIncrementStrategy implements BidIncrementStrategy {
    @Override
    public double minIncrement(double currentPrice) {
        return 5.0; // always require at least 5 above the current price
    }
}

// Observer interface: reacts to auction lifecycle events.
interface AuctionObserver {
    void onBidPlaced(Bid bid, double newPrice);                          // a valid bid changed the price or leader
    void onBidRejected(String bidderId, String auctionId, String reason);   // a bid was not accepted
    void onAuctionExtended(String auctionId, int newEndTime);                // anti sniping pushed the deadline later
    void onAuctionEnded(String auctionId, String winnerId, double finalPrice); // the auction closed
}

// Simple observer that prints events to the console.
