    @Override
    public void onBidPlaced(Bid bid, double newPrice) {
        System.out.println("Bid " + bid.getBidId() + " placed by " + bid.getBidderId() + ", new price " + newPrice);
    }

    @Override
    public void onBidRejected(String bidderId, String auctionId, String reason) {
        System.out.println("Bid rejected for " + bidderId + " on " + auctionId + ": " + reason);
    }

    @Override
