using namespace std;

// Strategy interface: how large a minimum increment above the current price is required.
class BidIncrementStrategy {
public:
    virtual double minIncrement(double currentPrice) = 0;
    virtual ~BidIncrementStrategy() {}
};

// A simple constant increment, regardless of how high the price has climbed.
class FixedIncrementStrategy : public BidIncrementStrategy {
public:
    double minIncrement(double currentPrice) override {
        return 5.0; // always require at least 5 above the current price
    }
};

// Observer interface: reacts to auction lifecycle events.
class AuctionObserver {
public:
    virtual void onBidPlaced(const Bid& bid, double newPrice) = 0;
    virtual void onBidRejected(const string& bidderId, const string& auctionId, const string& reason) = 0;
    virtual void onAuctionExtended(const string& auctionId, int newEndTime) = 0;
    virtual void onAuctionEnded(const string& auctionId, const string& winnerId, double finalPrice) = 0;
    virtual ~AuctionObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleAuctionObserver : public AuctionObserver {
public:
    void onBidPlaced(const Bid& bid, double newPrice) override {
        cout << "Bid " << bid.bidId << " placed by " << bid.bidderId << ", new price " << newPrice << endl;
    }
    void onBidRejected(const string& bidderId, const string& auctionId, const string& reason) override {
        cout << "Bid rejected for " << bidderId << " on " << auctionId << ": " << reason << endl;
    }
    void onAuctionExtended(const string& auctionId, int newEndTime) override {
        cout << "Auction " << auctionId << " extended to end time " << newEndTime << endl;
    }
    void onAuctionEnded(const string& auctionId, const string& winnerId, double finalPrice) override {
        cout << "Auction " << auctionId << " ended, winner " << winnerId << " at " << finalPrice << endl;
    }
};

