// Custom exceptions for the realistic failure modes.
class BidNotAllowedException extends RuntimeException {
    public BidNotAllowedException(String msg) { super(msg); }
}
class AuctionEndedException extends RuntimeException {
    public AuctionEndedException(String msg) { super(msg); }
}
class InvalidAuctionException extends RuntimeException {
    public InvalidAuctionException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class AuctionService {
    private final java.util.Map<String, Auction> auctions = new java.util.HashMap<>(); // auctionId -> Auction
    private final BidIncrementStrategy incrementStrategy; // pluggable increment policy
    private final java.util.List<AuctionObserver> observers = new java.util.ArrayList<>(); // listeners
    private static final int ANTI_SNIPE_WINDOW = 5;   // bids within this many time units of the end trigger an extension
    private static final int ANTI_SNIPE_EXTENSION = 10; // how far the deadline pushes out when triggered

    public AuctionService(BidIncrementStrategy incrementStrategy) {
        this.incrementStrategy = incrementStrategy; // store chosen policy
    }

    public void addAuction(Auction auction) { auctions.put(auction.getAuctionId(), auction); } // register an auction
    public void addObserver(AuctionObserver observer) { observers.add(observer); }                // register a listener

    // Places a proxy bid, running the real auction-house price algorithm and the anti sniping check.
    public synchronized Bid placeBid(String auctionId, String bidderId, double maxAmount, int currentTime, AuctionIdFactory factory) {
        Auction auction = auctions.get(auctionId);                          // look up auction
        if (auction == null) throw new InvalidAuctionException("Unknown auction: " + auctionId);
        if (currentTime >= auction.getEndTime()) {                            // auction already over
            throw new AuctionEndedException("Auction " + auctionId + " has already ended");
        }
        double requiredMinimum = auction.getCurrentPrice() + incrementStrategy.minIncrement(auction.getCurrentPrice()); // must clear this
        if (maxAmount < requiredMinimum) {                                      // bid does not clear the minimum
            for (AuctionObserver obs : observers) obs.onBidRejected(bidderId, auctionId, "Bid too low"); // notify
            throw new BidNotAllowedException("Bid must be at least " + requiredMinimum);
        }
        if (bidderId.equals(auction.getHighestBidderId())) {                     // already the current leader
            for (AuctionObserver obs : observers) obs.onBidRejected(bidderId, auctionId, "Already the highest bidder"); // notify
            throw new BidNotAllowedException(bidderId + " is already the highest bidder");
        }
        String bidId = factory.nextBidId();                                       // build id
        Bid bid = new Bid(bidId, auctionId, bidderId, maxAmount);                    // build the bid record
        if (auction.getHighestBidderId() == null) {                                    // this is the very first bid
            auction.setHighestBidderId(bidderId);                                        // this bidder leads
            auction.setHighestMax(maxAmount);                                              // their true maximum
            // currentPrice stays at the starting price, since there is no competitor to beat yet
        } else if (maxAmount > auction.getHighestMax()) {                              // new challenger beats the old leader
            double oldHighestMax = auction.getHighestMax();                              // remember the old ceiling
            double newPrice = Math.min(maxAmount, oldHighestMax + incrementStrategy.minIncrement(auction.getCurrentPrice())); // just enough to beat it
            auction.setHighestBidderId(bidderId);                                           // new bidder takes the lead
            auction.setHighestMax(maxAmount);                                                 // their true maximum
            auction.setCurrentPrice(newPrice);                                                  // update displayed price
        } else {                                                                          // old leader stays ahead
            double newPrice = Math.min(auction.getHighestMax(), maxAmount + incrementStrategy.minIncrement(auction.getCurrentPrice())); // just enough to beat the challenger
            auction.setCurrentPrice(newPrice);                                                // leader keeps lead at a higher price
        }
        for (AuctionObserver obs : observers) obs.onBidPlaced(bid, auction.getCurrentPrice()); // notify
        if (auction.getEndTime()-currentTime <= ANTI_SNIPE_WINDOW) {                     // this bid arrived late
            int newEndTime = currentTime + ANTI_SNIPE_EXTENSION;                            // push the deadline out
            auction.setEndTime(newEndTime);                                                   // apply the extension
            for (AuctionObserver obs : observers) obs.onAuctionExtended(auctionId, newEndTime); // notify
        }
        return bid; // hand back to caller
    }
}

