#include <string>
#include <vector>
#include <map>
#include <memory>
#include <algorithm>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class BidNotAllowedException : public runtime_error {
public: BidNotAllowedException(const string& msg) : runtime_error(msg) {}
};
class AuctionEndedException : public runtime_error {
public: AuctionEndedException(const string& msg) : runtime_error(msg) {}
};
class InvalidAuctionException : public runtime_error {
public: InvalidAuctionException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class AuctionService {
    map<string, Auction> auctions;                        // auctionId -> Auction
    shared_ptr<BidIncrementStrategy> incrementStrategy;  // pluggable increment policy
    vector<shared_ptr<AuctionObserver>> observers;      // listeners
    static const int ANTI_SNIPE_WINDOW = 5;                // bids within this many time units of the end trigger an extension
    static const int ANTI_SNIPE_EXTENSION = 10;              // how far the deadline pushes out when triggered

public:
    AuctionService(shared_ptr<BidIncrementStrategy> strategy) : incrementStrategy(strategy) {}

    void addAuction(Auction auction) { auctions.insert({auction.auctionId, auction}); } // register an auction
    void addObserver(shared_ptr<AuctionObserver> observer) { observers.push_back(observer); } // register a listener

    Bid placeBid(string auctionId, string bidderId, double maxAmount, int currentTime, AuctionIdFactory& factory) {
        auto it = auctions.find(auctionId);                            // look up auction
        if (it == auctions.end()) throw InvalidAuctionException("Unknown auction: " + auctionId);
        Auction& auction = it->second;
        if (currentTime >= auction.endTime) {                             // auction already over
            throw AuctionEndedException("Auction " + auctionId + " has already ended");
        }
        double requiredMinimum = auction.currentPrice + incrementStrategy->minIncrement(auction.currentPrice); // must clear this
        if (maxAmount < requiredMinimum) {                                   // bid does not clear the minimum
            for (auto& obs : observers) obs->onBidRejected(bidderId, auctionId, "Bid too low"); // notify
            throw BidNotAllowedException("Bid must be at least " + to_string(requiredMinimum));
        }
        if (bidderId == auction.highestBidderId) {                            // already the current leader
            for (auto& obs : observers) obs->onBidRejected(bidderId, auctionId, "Already the highest bidder"); // notify
            throw BidNotAllowedException(bidderId + " is already the highest bidder");
        }
        string bidId = factory.nextBidId();                                    // build id
        Bid bid(bidId, auctionId, bidderId, maxAmount);                          // build the bid record
        if (auction.highestBidderId.empty()) {                                    // this is the very first bid
            auction.highestBidderId = bidderId;                                      // this bidder leads
            auction.highestMax = maxAmount;                                             // their true maximum
            // currentPrice stays at the starting price, since there is no competitor to beat yet
        } else if (maxAmount > auction.highestMax) {                                // new challenger beats the old leader
            double oldHighestMax = auction.highestMax;                                // remember the old ceiling
            double newPrice = min(maxAmount, oldHighestMax + incrementStrategy->minIncrement(auction.currentPrice)); // just enough to beat it
            auction.highestBidderId = bidderId;                                          // new bidder takes the lead
            auction.highestMax = maxAmount;                                                // their true maximum
            auction.currentPrice = newPrice;                                                // update displayed price
        } else {                                                                       // old leader stays ahead
            double newPrice = min(auction.highestMax, maxAmount + incrementStrategy->minIncrement(auction.currentPrice)); // just enough to beat the challenger
            auction.currentPrice = newPrice;                                              // leader keeps lead at a higher price
        }
        for (auto& obs : observers) obs->onBidPlaced(bid, auction.currentPrice);       // notify
        if (auction.endTime-currentTime <= ANTI_SNIPE_WINDOW) {                          // this bid arrived late
            int newEndTime = currentTime + ANTI_SNIPE_EXTENSION;                           // push the deadline out
            auction.endTime = newEndTime;                                                   // apply the extension
            for (auto& obs : observers) obs->onAuctionExtended(auctionId, newEndTime);         // notify
        }
        return bid; // hand back to caller
    }
};

