        service.placeBid("A1", "Carol", 210.0, 25, factory);

        try {
            service.placeBid("A1", "Bob", 500.0, 41, factory);
        } catch (AuctionEndedException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }
    }
}

