#include <memory>
#include <algorithm>
#include <stdexcept>
using namespace std;

enum class AuctionStatus { ACTIVE, ENDED };

class Item {
public:
    string itemId;
    string title;
    double startingPrice;

    Item() {}
    Item(string id, string t, double price) : itemId(id), title(t), startingPrice(price) {}
};

class Auction {
public:
    string auctionId;
    string itemId;
    string sellerId;
    string highestBidderId;
    double highestMax;
    double currentPrice;
    int endTime;
    AuctionStatus status;

    Auction() : highestMax(0.0), currentPrice(0.0), endTime(0), status(AuctionStatus::ACTIVE) {}
    Auction(string id, string item, string seller, double startingPrice, int end)
        : auctionId(id), itemId(item), sellerId(seller), highestBidderId(""), highestMax(0.0),
          currentPrice(startingPrice), endTime(end), status(AuctionStatus::ACTIVE) {}
};

class Bid {
public:
    string bidId;
    string auctionId;
    string bidderId;
    double maxAmount;

    Bid() : maxAmount(0.0) {}
    Bid(string id, string auction, string bidder, double amount)
        : bidId(id), auctionId(auction), bidderId(bidder), maxAmount(amount) {}
};

class AuctionIdFactory {
    int auctionCounter = 0;
    int bidCounter = 0;

public:
    string nextAuctionId() {
        auctionCounter++;
        return "A" + to_string(auctionCounter);
    }

    string nextBidId() {
        bidCounter++;
        return "B" + to_string(bidCounter);
    }
};

class BidIncrementStrategy {
public:
    virtual double minIncrement(double currentPrice) = 0;
    virtual ~BidIncrementStrategy() {}
};

class FixedIncrementStrategy : public BidIncrementStrategy {
public:
    double minIncrement(double currentPrice) override {
        return 5.0;
    }
};

class AuctionObserver {
public:
    virtual void onBidPlaced(const Bid& bid, double newPrice) = 0;
    virtual void onBidRejected(const string& bidderId, const string& auctionId, const string& reason) = 0;
    virtual void onAuctionExtended(const string& auctionId, int newEndTime) = 0;
    virtual void onAuctionEnded(const string& auctionId, const string& winnerId, double finalPrice) = 0;
    virtual ~AuctionObserver() {}
};

class ConsoleAuctionObserver : public AuctionObserver {
public:
    void onBidPlaced(const Bid& bid, double newPrice) override {
        cout << "Bid " << bid.bidId << " placed by " << bid.bidderId << ", new price " << newPrice << endl;
    }
    void onBidRejected(const string& bidderId, const string& auctionId, const string& reason) override {
        cout << "Bid rejected for " << bidderId << " on " << auctionId << ": " << reason << endl;
    }
    void onAuctionExtended(const string& auctionId, int newEndTime) override {
        cout << "Auction " << auctionId << " extended to end time " << newEndTime << endl;
    }
    void onAuctionEnded(const string& auctionId, const string& winnerId, double finalPrice) override {
        cout << "Auction " << auctionId << " ended, winner " << winnerId << " at " << finalPrice << endl;
    }
};

class BidNotAllowedException : public runtime_error {
public: BidNotAllowedException(const string& msg) : runtime_error(msg) {}
};
class AuctionEndedException : public runtime_error {
public: AuctionEndedException(const string& msg) : runtime_error(msg) {}
};
class InvalidAuctionException : public runtime_error {
public: InvalidAuctionException(const string& msg) : runtime_error(msg) {}
};

class AuctionService {
    map<string, Auction> auctions;
    shared_ptr<BidIncrementStrategy> incrementStrategy;
    vector<shared_ptr<AuctionObserver>> observers;
    static const int ANTI_SNIPE_WINDOW = 5;
    static const int ANTI_SNIPE_EXTENSION = 10;

public:
    AuctionService(shared_ptr<BidIncrementStrategy> strategy) : incrementStrategy(strategy) {}

    void addAuction(Auction auction) { auctions.insert({auction.auctionId, auction}); }
    void addObserver(shared_ptr<AuctionObserver> observer) { observers.push_back(observer); }

    Bid placeBid(string auctionId, string bidderId, double maxAmount, int currentTime, AuctionIdFactory& factory) {
        auto it = auctions.find(auctionId);
        if (it == auctions.end()) throw InvalidAuctionException("Unknown auction: " + auctionId);
        Auction& auction = it->second;
        if (currentTime >= auction.endTime) {
            throw AuctionEndedException("Auction " + auctionId + " has already ended");
        }
        double requiredMinimum = auction.currentPrice + incrementStrategy->minIncrement(auction.currentPrice);
        if (maxAmount < requiredMinimum) {
            for (auto& obs : observers) obs->onBidRejected(bidderId, auctionId, "Bid too low");
            throw BidNotAllowedException("Bid must be at least " + to_string(requiredMinimum));
        }
        if (bidderId == auction.highestBidderId) {
            for (auto& obs : observers) obs->onBidRejected(bidderId, auctionId, "Already the highest bidder");
            throw BidNotAllowedException(bidderId + " is already the highest bidder");
        }
        string bidId = factory.nextBidId();
        Bid bid(bidId, auctionId, bidderId, maxAmount);
        if (auction.highestBidderId.empty()) {
            auction.highestBidderId = bidderId;
            auction.highestMax = maxAmount;
        } else if (maxAmount > auction.highestMax) {
            double oldHighestMax = auction.highestMax;
            double newPrice = min(maxAmount, oldHighestMax + incrementStrategy->minIncrement(auction.currentPrice));
            auction.highestBidderId = bidderId;
            auction.highestMax = maxAmount;
            auction.currentPrice = newPrice;
        } else {
            double newPrice = min(auction.highestMax, maxAmount + incrementStrategy->minIncrement(auction.currentPrice));
            auction.currentPrice = newPrice;
        }
        for (auto& obs : observers) obs->onBidPlaced(bid, auction.currentPrice);
        if (auction.endTime-currentTime <= ANTI_SNIPE_WINDOW) {
            int newEndTime = currentTime + ANTI_SNIPE_EXTENSION;
            auction.endTime = newEndTime;
            for (auto& obs : observers) obs->onAuctionExtended(auctionId, newEndTime);
        }
        return bid;
    }
};

int main() {
    auto service = AuctionService(make_shared<FixedIncrementStrategy>());
    service.addObserver(make_shared<ConsoleAuctionObserver>());
    AuctionIdFactory factory;

    Auction auction("A1", "ITEM1", "Seller", 100.0, 20);
    service.addAuction(auction);

    service.placeBid("A1", "Alice", 150.0, 0, factory);
    service.placeBid("A1", "Bob", 120.0, 1, factory);
    service.placeBid("A1", "Carol", 200.0, 2, factory);

    try {
        service.placeBid("A1", "Bob", 140.0, 3, factory);
    } catch (BidNotAllowedException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    service.placeBid("A1", "Dave", 250.0, 18, factory);
    service.placeBid("A1", "Carol", 210.0, 25, factory);

    try {
        service.placeBid("A1", "Bob", 500.0, 41, factory);
    } catch (AuctionEndedException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    return 0;
}
